def owners_to_memberships(apps, schema_editor):
    """Each company's single owner becomes its first team member (role
    owner) and is recorded as the person who created it."""
    Company = apps.get_model("companies", "Company")
    Membership = apps.get_model("companies", "CompanyMembership")
    for company in Company.objects.exclude(owner=None).iterator():
        Membership.objects.get_or_create(user_id=company.owner_id, defaults={"company": company, "role": "owner"})
        company.created_by_id = company.owner_id
        company.save(update_fields=["created_by"])


def memberships_to_owners(apps, schema_editor):
    """Reverse: the earliest owner becomes the single owner again. Other
    team members are dropped by the reverse of CreateModel."""
    Company = apps.get_model("companies", "Company")
    Membership = apps.get_model("companies", "CompanyMembership")
    for company in Company.objects.all().iterator():
        first = Membership.objects.filter(company=company, role="owner").order_by("created_at").first()
        company.owner_id = first.user_id if first else company.created_by_id
        company.save(update_fields=["owner"])


